  mounted.connected.rail.select("a");

  const body = mounted.container.querySelector<HTMLElement>(".pane-body")!;

  body.getBoundingClientRect = () => new DOMRect(0, 0, 100, 100);
  await Promise.resolve();

  return { ...mounted, body };
}

